import random

STATION_LIMITS = ((1, 6), (1, 6), (1, 4), (1, 6), (1, 6))
WARMUP_PERIODS = 1_000
MEASURED_PERIODS = 20_000
REPLICATIONS = 20


def run_replication(seed):
    rng = random.Random(seed)

    # buffers[i] is the buffer immediately after station i + 1.
    buffers = [0] * (len(STATION_LIMITS) - 1)
    total_finished = 0

    for period in range(WARMUP_PERIODS + MEASURED_PERIODS):
        finished_this_period = 0

        for station, (low, high) in enumerate(STATION_LIMITS):
            capacity = rng.randint(low, high)

            if station == 0:
                # Station 1 has unlimited raw material.
                moved = capacity
            else:
                moved = min(capacity, buffers[station - 1])
                buffers[station - 1] -= moved

            if station == len(STATION_LIMITS) - 1:
                finished_this_period += moved
            else:
                # Units are available to the next station this period.
                buffers[station] += moved

        if period >= WARMUP_PERIODS:
            total_finished += finished_this_period

    return total_finished


def main():
    mean_capacities = [(low + high) / 2.0 for low, high in STATION_LIMITS]
    minimum_mean = min(mean_capacities)

    if all(mean == minimum_mean for mean in mean_capacities):
        bottleneck = "none"
    else:
        bottleneck = str(mean_capacities.index(minimum_mean) + 1)

    total_finished = sum(
        run_replication(seed=10_000 + replication)
        for replication in range(REPLICATIONS)
    )
    throughput = total_finished / (REPLICATIONS * MEASURED_PERIODS)

    print(f"BOTTLENECK: {bottleneck}")
    print(f"THROUGHPUT: {throughput:.10f}")


if __name__ == "__main__":
    main()
