import random

STATION_MEANS = (4.0, 3.0, 4.0, 4.0, 4.0)
STATION_SDS = (0.5,) * len(STATION_MEANS)

WARMUP_PERIODS = 2000
MEASURED_PERIODS = 20000
REPLICATIONS = 20
BASE_SEED = 20250308


def simulate_replication(seed):
    rng = random.Random(seed)
    n = len(STATION_MEANS)

    # buffers[i] is the buffer immediately before station i + 1.
    buffers = [0] * (n - 1)
    total_finished = 0

    for period in range(WARMUP_PERIODS + MEASURED_PERIODS):
        capacities = [
            max(0, int(round(rng.gauss(mean, sd))))
            for mean, sd in zip(STATION_MEANS, STATION_SDS)
        ]

        finished = 0

        # Process stations in order so units can cross several stations
        # during the same period.
        for station in range(n):
            if station == 0:
                # Station 1 has unlimited raw material.
                moved = capacities[station]
            else:
                moved = min(capacities[station], buffers[station - 1])

            if station < n - 1:
                buffers[station] += moved
            else:
                finished = moved

        if period >= WARMUP_PERIODS:
            total_finished += finished

    return total_finished


def main():
    total_finished = sum(
        simulate_replication(BASE_SEED + replication)
        for replication in range(REPLICATIONS)
    )
    throughput = total_finished / (REPLICATIONS * MEASURED_PERIODS)

    # The configured means are the stations' average capacities.
    minimum_mean = min(STATION_MEANS)
    if all(mean == minimum_mean for mean in STATION_MEANS):
        bottleneck = "none"
    else:
        bottleneck = str(STATION_MEANS.index(minimum_mean) + 1)

    print(f"BOTTLENECK: {bottleneck}")
    print(f"THROUGHPUT: {throughput:.6f}")


if __name__ == "__main__":
    main()
